MagickBooleanType SkipUncompressedMipmaps(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  if (EOFBlob(image)) {
    return MagickFalse;
  }

  if ((dds_info->mipmaps > 0) && ((dds_info->texture) || (dds_info->cube_map))) {
    size_t width = dds_info->width;
    size_t height = dds_info->height;

    for (size_t level = 0; level < dds_info->mipmaps; level++) {
      size_t mipmap_width = width > 0 ? width : 1;
      size_t mipmap_height = height > 0 ? height : 1;
      size_t mipmap_size = mipmap_width * mipmap_height * pixel_size;

      if (SeekBlob(image, mipmap_size, SEEK_CUR) == MagickFalse) {
        return MagickFalse;
      }

      if (mipmap_width > 1) {
        mipmap_width >>= 1;
      } else {
        mipmap_width = 0;
      }

      if (mipmap_height > 1) {
        mipmap_height >>= 1;
      } else {
        mipmap_height = 0;
      }

      width = mipmap_width;
      height = mipmap_height;
    }
  }

  return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmaps(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
  if ((dds_info->mipmap_levels > 1) && (dds_info->dds_flags & (DDSD_TEXTURE | DDSD_CUBEMAP))) {
    size_t width = dds_info->width;
    size_t height = dds_info->height;

    for (size_t level = 1; (level < dds_info->mipmap_levels) && (width > 0) && (height > 0); level++) {
      size_t mipmap_width = MagickMax(1UL, width >> 1);
      size_t mipmap_height = MagickMax(1UL, height >> 1);
      size_t mipmap_size = mipmap_width * mipmap_height * pixel_size;

      if (SeekBlob(image, mipmap_size, SEEK_CUR) != ( MagickOffsetType ) mipmap_size)
        return MagickFalse;

      width = mipmap_width;
      height = mipmap_height;
    }
  }

  return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmapDDSImages(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  if ((dds_info->has_mipmap) && (dds_info->ddshdr.dds_header.dwFlags & DDSD_MIPMAPCOUNT)) {
    int width = (dds_info->ddshdr.dds_header.dwWidth);
    int height = (dds_info->ddshdr.dds_header.dwHeight);
    size_t row_size = (size_t)(width * (size_t)pixel_size);
    ssize_t skip_size = 0;

    while ((width > 0) && (height > 0)) {
      skip_size = (ssize_t)(row_size * (size_t)height);
      if (image->length < (size_t)skip_size) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnexpectedEndOfFile", "\n");
        return MagickFalse;
      }
      image->length -= (size_t)skip_size;
      image->offset += (size_t)skip_size;
      if (width > 1)
        width >>= 1;
      else
        width = 0;
      if (height > 1)
        height >>= 1;
      else
        height = 0;
    }

    return MagickTrue;
  }

  return MagickFalse;
}

MagickBooleanType SkipUncompressedMipmaps(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  size_t level = 0;
  size_t width = dds_info->width;
  size_t height = dds_info->height;
  size_t depth = dds_info->depth;

  if ((dds_info->mipmaps) && ((dds_info->flags & DDS_TEXTURE) != 0 || (dds_info->flags & DDS_CUBEMAP) != 0)) {
    while ((width != 0) || (height != 0) || (depth != 0)) {
      size_t row_bytes = width * pixel_size;
      size_t image_size = row_bytes * height * depth;

      if (SeekBlob(image, image_size, SEEK_CUR) == -1) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnexpectedEndOfFile", " while reading mipmap level %zu", level);
        return MagickFalse;
      }

      width = (width > 1) ? width / 2 : 0;
      height = (height > 1) ? height / 2 : 0;
      depth = (depth > 1) ? depth / 2 : 0;
      level++;
    }
  }

  return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
  if (dds_info->mipmap_levels > 1) {
    size_t width = dds_info->width;
    size_t height = dds_info->height;
    size_t depth = dds_info->depth;
    size_t skip_size;

    for (size_t level = 1; (width > 0) && (height > 0) && (depth > 0); level++) {
      width = width > 1 ? width / 2 : 1;
      height = height > 1 ? height / 2 : 1;
      depth = depth > 1 ? depth / 2 : 1;

      skip_size = width * height * depth * pixel_size;
      if (SeekBlob(image, skip_size, SEEK_CUR) != (MagickOffsetType)TellBlob(image)) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                    "UnexpectedEndOfFile", "`%s' (DDS)", image->filename);
        return MagickFalse;
      }
    }
    return MagickFalse;
  }
  return MagickTrue;
}
